CREATE TABLE IF NOT EXISTS product_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NULL, case_id uuid NULL, event_name text NOT NULL, path text NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, visitor_id text NOT NULL, session_id text NOT NULL, utm_source text NULL, utm_medium text NULL, utm_campaign text NULL, utm_content text NULL, utm_term text NULL, created_at timestamptz NOT NULL DEFAULT now())